def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 10:
        return 'C'

    opp_def = 0
    my_def = 0
    for a, o in history:
        if o == 'D':
            opp_def += 1
        if a == 'D':
            my_def += 1
    opp_rate = opp_def / n

    if opp_rate > 0.8:
        return 'D'

    if opp_rate > 0.3:
        first_D = -1
        for i, (a, _) in enumerate(history):
            if a == 'D':
                first_D = i
                break
        if first_D == -1:
            return 'D'
        if (n - first_D) % 10 == 0:
            return 'D'
        else:
            return 'C'

    if n >= 22 and history[20][0] == 'D' and history[21][1] == 'C':
        return 'D'

    recent5 = history[-5:] if n >= 5 else history
    opp_def5 = 0
    for _, o in recent5:
        if o == 'D':
            opp_def5 += 1

    if n >= 90 and opp_def5 >= 1:
        return 'D'

    if n == 99:
        return 'D'

    if n == 20 and opp_def == 0 and my_def == 0:
        return 'D'

    if opp_def5 >= 2:
        return 'D'

    return 'C'
